import{z as p,x as A,o as r,c as B,q as i,j as n,D as o,d as e,s as l,S as E,b as t}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"离散概率够用的那一层","description":"","frontmatter":{"title":"离散概率够用的那一层","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/discrete-probability.md","filePath":"cs/discrete-probability.md","lastUpdated":1791413859000}'),d={name:"cs/discrete-probability.md"};function m(c,a,h,b,P,C){const s=A("Mermaid");return r(),B("div",null,[a[2]||(a[2]=i('<h1 id="离散概率够用的那一层" tabindex="-1">离散概率够用的那一层 <a class="header-anchor" href="#离散概率够用的那一层" aria-label="Permalink to &quot;离散概率够用的那一层&quot;">​</a></h1><div class="epigraph"><p>有限样本空间上，概率是点的权重之和为 1；期望是线性的，不必先谈密度。</p><footer>—— 据 Rosen, Discrete Mathematics and Its Applications；Shannon, 1948 整理</footer></div><p>上一课<a href="/cs/counting-combinatorics">组合计数</a>钉死了 \\(|\\Omega|\\) 怎么来。本课不重讲 \\(\\binom{n}{k}\\)，也不从测度论另起。<a href="/cs/entropy-bits">熵</a>已经用过 \\(p(x)\\)，当时声明公理后补。缺口是：把有限空间上的 \\(p\\)、事件、条件、期望写清，使熵、后课随机算法、误码率有同一套语言。信息与离散的主干到此还剩期望线性与条件贝叶斯两课。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>计数给均匀：\\(P(A)=|A|/|\\Omega|\\)。非均匀时每个原子有 \\(p_\\omega\\ge 0\\)、\\(\\sum p_\\omega=1\\)。缺口因此不是再数一遍，而是事件代数（这里有限，就是幂集）、条件概率 \\(P(A|B)=P(A\\cap B)/P(B)\\)、独立、期望线性 \\(\\mathbb{E}[X+Y]=\\mathbb{E}[X]+\\mathbb{E}[Y]\\)（无需独立）。</p><p>熵 \\(H(X)=-\\sum p\\log p\\) 现在是本课期望的实例。误码、后课 DRAM 刷新失败，都先建成有限或可数支撑的 \\(p\\)，不把高斯密度请进来。</p><h3 id="独立不是「没有关系」的散文" tabindex="-1">独立不是「没有关系」的散文 <a class="header-anchor" href="#独立不是「没有关系」的散文" aria-label="Permalink to &quot;独立不是「没有关系」的散文&quot;">​</a></h3><p>\\(P(A\\cap B)=P(A)P(B)\\)。不独立的典型：同一比特上的两个事件。后课哈希「独立散列」是更强的设计假设，本课只钉定义。也不把期望当成「最可能的值」：期望可以不是支撑上的点。</p><p><span class="marginnote">Rosen 的离散概率章与本课同层。Shannon 的 \\(p\\) 现在有分母。连续概率、大数定律的证明不进主干；后课需要时用直觉「样本均值靠近期望」。</span></p><p><span class="marginnote">数字实例看「期望线性无需独立」：掷两个骰子，点数和的期望 \\(\\mathbb{E}[X+Y]=3.5+3.5=7\\)。两个骰子当然独立，但你把其中一枚换成「必然与另一枚同点」的作弊骰，答案仍是 \\(3.5+3.5=7\\)——线性只对求和分配，从不问两个变量怎么耦合。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>\\(\\Omega\\) 有限。随机变量是函数 \\(X:\\Omega\\to\\mathbb{R}\\)（后课常取有限值）。线性、全期望、贝叶斯在有限和里就是改求和次序。伯努利、二项来自独立重复抛币，对应比特翻转模型：后课 ECC 的「至多 \\(t\\) 位错」是事件，概率用二项或并界估计。</p>',12)),(r(),n(E,null,{default:o(()=>[l(s,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20CNT%5B%22%7C%CE%A9%7C%22%5D%20--%3E%20P%5B%22%E6%A6%82%E7%8E%87%E8%B4%A8%E9%87%8F%22%5D%0A%20%20P%20--%3E%20EXP%5B%22%E6%9C%9F%E6%9C%9B%E7%BA%BF%E6%80%A7%22%5D%0A%20%20P%20--%3E%20ENT%5B%22%E7%86%B5%E5%B7%B2%E6%9C%89%E5%AE%9A%E4%B9%89%22%5D%0A%20%20EXP%20--%3E%20LATER%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9ACMOS%20%E5%AE%9E%E7%8E%B0%E6%AF%94%E7%89%B9%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t("h2",{id:"机制",tabindex:"-1"},[e("机制 "),t("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=t("p",null,[e("有了这层，误码率、哈希碰撞概率、快排期望比较次数才有对象。本课不把那些算法写完。组合逻辑险象是确定的，不是概率；器件噪声才是概率，"),t("a",{href:"/cs/cmos-inverter"},"CMOS"),e("也不把热噪声量化，只实现判决。")],-1)),a[5]||(a[5]=t("p",null,"条件独立在贝叶斯网上是后话；本课够用全概率公式切分。",-1)),(r(),n(E,null,{default:o(()=>[l(s,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20X%5B%22%E5%8F%91%E9%80%81%E6%AF%94%E7%89%B9%201%EF%BC%9AP%3D0.6%22%5D%20--%3E%20OK%5B%22%E4%BF%A1%E9%81%93%E6%97%A0%E8%AF%AF%EF%BC%9AP%3D0.9%22%5D%0A%20%20X%20--%3E%20FL%5B%22%E7%BF%BB%E8%BD%AC%E6%88%90%200%EF%BC%9AP%3D0.1%22%5D%0A%20%20OK%20--%3E%20R1%5B%22%E6%94%B6%E5%88%B0%201%EF%BC%9A0.6%C3%970.9%3D0.54%22%5D%0A%20%20FL%20--%3E%20R0%5B%22%E6%94%B6%E5%88%B0%200%EF%BC%9A0.6%C3%970.1%3D0.06%22%5D%0A%20%20Y%5B%22%E5%8F%91%E9%80%81%E6%AF%94%E7%89%B9%200%EF%BC%9AP%3D0.4%22%5D%20--%3E%20OK2%5B%22%E6%97%A0%E8%AF%AF%EF%BC%9A0.4%C3%970.9%3D0.36%22%5D%0A%20%20Y%20--%3E%20FL2%5B%22%E7%BF%BB%E8%BD%AC%E6%88%90%201%EF%BC%9A0.4%C3%970.1%3D0.04%22%5D%0A%20%20FL2%20--%3E%20R1%0A%20%20OK2%20--%3E%20R0%0A"})]),fallback:o(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=i('<p>这张图回答「收到 1 时发送的是 1 的概率怎么算」：沿树把两条通往「收到 1」的路径概率相加得 \\(0.54+0.04=0.58\\)，再除以 \\(P(\\text{收到 1})=0.58\\)，得 \\(0.54/0.58\\approx 0.93\\)。这就是贝叶斯的全部算术：先按原因分叉，再按证据收口。</p><p><span class="marginnote">直觉类比：条件概率就是「删世界」。\\(P(A\\mid B)\\) 的分母 \\(P(B)\\) 把所有 \\(B\\) 没发生的世界整个划掉，分子只留下 \\(B\\) 和 \\(A\\) 同时发生的那些，再看 \\(A\\) 占剩下世界的多大比例——不是 \\(A\\) 变了，是你在数一个更小的宇宙。</span></p><p><span class="marginnote">直觉类比：把 \\(-\\log p\\) 想成「惊讶度」——必然事件（\\(p=1\\)）发生毫不惊讶，记 0；万分之一的事发生，惊讶度约 13.3 比特。熵 \\(H(X)=-\\sum p\\log p\\) 就是按概率加权的平均惊讶度，也就是这篇课所说的「熵是 \\(-\\log p\\) 的期望」。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 \\(\\sigma\\)-代数、勒贝格积分、随机过程。也不把金融栏的测度换元请进来。大模型栏的 token 分布是另一张表，本栏不重写。</p><p>后课默认：有限随机对象用质量函数；期望可拆开。均匀时回到计数比。下一课把期望的线性性钉成计算工具，条件反转再下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>有限 \\(\\Omega\\) 上概率是归一化权重；均匀则回到 \\(|A|/|\\Omega|\\)。</li><li>期望线性不需独立；熵是 \\(-\\log p\\) 的期望。</li><li>连续分布不进本栏主干。数字逻辑课在概率与数值各课之后才开始。</li><li>出处：Rosen；Shannon, 1948。</li></ul>',8))])}const F=p(d,[["render",m]]);export{u as __pageData,F as default};
